// Computa severidad y formatea mensaje para Telegram
const body = $input.item.json.body || $input.item.json;
const analysis = body.analysis || {};
const flags = analysis.flags || [];
const sentiment = analysis.sentiment ?? 0;
const opportunity = analysis.opportunity_score ?? 0;
const risk = analysis.risk_score ?? 0;
const text = body.text || '(sin texto)';
const summary = analysis.summary_es || '(sin resumen)';
const conversacion_id = body.conversacion_id || null;
const customer = body.customer_name || 'Anónimo';

let severity = 'baja';
let emoji = '🟢';
let title = 'EVENTO BAJO';
let tipo = 'low_priority';

if (flags.includes('legal_mention')) {
  severity = 'critica';
  emoji = '🚨';
  title = 'ALERTA CRÍTICA · MENCIÓN LEGAL';
  tipo = 'legal_mention';
} else if (flags.includes('bad_language')) {
  severity = 'critica';
  emoji = '🚨';
  title = 'ALERTA CRÍTICA · LENGUAJE AGRESIVO';
  tipo = 'bad_language';
} else if (sentiment < -0.5) {
  severity = 'alta';
  emoji = '🟠';
  title = 'ALERTA ALTA · SENTIMENT NEGATIVO';
  tipo = 'sentiment_drop';
} else if (flags.includes('escalation_request')) {
  severity = 'media';
  emoji = '🟡';
  title = 'CLIENTE PIDE HUMANO';
  tipo = 'escalation_request';
} else if (opportunity > 0.8) {
  severity = 'media';
  emoji = '💎';
  title = 'OPORTUNIDAD CALIENTE';
  tipo = 'high_value_opportunity';
}

// Formatear mensaje Telegram (Markdown)
const message = `${emoji} *${title}*\n\n` +
  `*Cliente:* ${customer}\n` +
  `*Sentiment:* ${sentiment} | *Risk:* ${risk} | *Opp:* ${opportunity}\n` +
  (flags.length > 0 ? `*Flags:* ${flags.join(', ')}\n` : '') +
  `\n📝 *Mensaje del cliente:*\n_${text.substring(0, 300)}${text.length > 300 ? '...' : ''}_\n\n` +
  `🔍 *Análisis IA:*\n${summary}\n\n` +
  `🔗 *Conversación ID:* ${conversacion_id ?? 'sin asignar'}`;

return {
  severity,
  tipo,
  emoji,
  title,
  message,
  conversacion_id,
  customer,
  shouldNotifyTelegram: severity !== 'baja'
};

